def _has_code(func: Optional[Callable[..., Any]], code: CodeType) ->Optional[
    Callable[..., Any]]:
    if func is None:
        return None
    if hasattr(func, '__code__') and func.__code__ is code:
        return func
    return None

def get_func(frame: FrameType) ->Optional[Callable[..., Any]]:
    code = frame.f_code
    func_name = code.co_name

    if func_name in frame.f_locals:
        candidate = frame.f_locals[func_name]
        result = _has_code(candidate, code)
        if result is not None:
            return result

    if func_name in frame.f_globals:
        candidate = frame.f_globals[func_name]
        result = _has_code(candidate, code)
        if result is not None:
            return result

    for obj in get_locals_from_previous_frames(frame):
        if obj is None:
            continue
        try:
            result = get_func_in_mro(obj, code)
            if result is not None:
                return result
        except (AttributeError, TypeError):
            continue

    return None
